"""
Fixture factory: builds validation captures whose TLS bytes come from a real
TLS implementation.

How the captures are produced
-----------------------------
* TLS handshakes and records are generated by OpenSSL (Python ``ssl`` module)
  through memory BIOs: a real client and a real server negotiate, so ClientHello,
  ServerHello, Certificate chains, key exchange, alerts and encrypted records are
  genuine OpenSSL output - including TLS 1.3 encrypting its certificate.
* SMTP / IMAP / POP3 plaintext dialogues follow the respective RFCs.
* The TCP/IP framing is synthesised with correctly tracked sequence numbers; TCP
  impairments (reordering, retransmission, loss, conflicting overlap) are
  applied deliberately and recorded in the ground truth.
* Certificates are issued relative to the *capture* timestamp, so validity is
  consistent inside each capture.

The one hand-built TLS case is ``smtp_tls12_3des_synthetic``: OpenSSL 3 no longer
negotiates 3DES/RC4, so that ServerHello is crafted and labelled synthetic.

Run:  python -m tests.robustness.fixture_factory   (from backend/)
"""
import json
import os
import ssl
import struct
import tempfile
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Callable, List, Optional, Tuple

import dpkt
from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa, ec, dh
from cryptography.x509.oid import NameOID

BASE = Path(__file__).parent / "fixtures"
PCAP_DIR = BASE / "pcaps"
GT_DIR = BASE / "ground_truth"

CAPTURE_EPOCH = 1740823200.0  # 2025-03-01T10:00:00Z
CAPTURE_DT = datetime.fromtimestamp(CAPTURE_EPOCH, timezone.utc)


# --------------------------------------------------------------------- PKI
@dataclass
class Issued:
    cert: x509.Certificate
    key: object

    @property
    def der(self) -> bytes:
        return self.cert.public_bytes(serialization.Encoding.DER)

    @property
    def pem(self) -> bytes:
        return self.cert.public_bytes(serialization.Encoding.PEM)

    @property
    def key_pem(self) -> bytes:
        return self.key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8,
                                      serialization.NoEncryption())


def _name(cn: str) -> x509.Name:
    return x509.Name([x509.NameAttribute(NameOID.ORGANIZATION_NAME, "SecureMailScope Test PKI"),
                      x509.NameAttribute(NameOID.COMMON_NAME, cn)])


def issue(cn: str, *, issuer: Optional[Issued] = None, ca: bool = False, san: Optional[List[str]] = None,
          key_bits: int = 2048, ec_key: bool = False, not_before: Optional[datetime] = None,
          not_after: Optional[datetime] = None, sig_hash=None) -> Issued:
    key = ec.generate_private_key(ec.SECP256R1()) if ec_key else \
        rsa.generate_private_key(public_exponent=65537, key_size=key_bits)
    nb = not_before or CAPTURE_DT - timedelta(days=30)
    na = not_after or CAPTURE_DT + timedelta(days=335)
    builder = (x509.CertificateBuilder()
               .subject_name(_name(cn))
               .issuer_name(issuer.cert.subject if issuer else _name(cn))
               .public_key(key.public_key())
               .serial_number(x509.random_serial_number())
               .not_valid_before(nb).not_valid_after(na)
               .add_extension(x509.BasicConstraints(ca=ca, path_length=None), critical=True))
    if san:
        builder = builder.add_extension(x509.SubjectAlternativeName([x509.DNSName(n) for n in san]), critical=False)
    signer = issuer.key if issuer else key
    cert = builder.sign(signer, sig_hash or hashes.SHA256())
    return Issued(cert, key)


def pki_chain(leaf_cn="mail.example.org", san=None, **leaf_kw) -> Tuple[Issued, Issued, Issued]:
    root = issue("SecureMailScope Test Root CA", ca=True, not_before=CAPTURE_DT - timedelta(days=3000),
                 not_after=CAPTURE_DT + timedelta(days=3000))
    inter = issue("SecureMailScope Test Issuing CA", issuer=root, ca=True,
                  not_before=CAPTURE_DT - timedelta(days=1000), not_after=CAPTURE_DT + timedelta(days=1000))
    leaf = issue(leaf_cn, issuer=inter, san=san or [leaf_cn], **leaf_kw)
    return root, inter, leaf


# --------------------------------------------------------------------- TLS
def server_ctx(chain: List[Issued], key_owner: Issued, *, min_v=None, max_v=None, ciphers=None,
               dh_params_pem: Optional[bytes] = None, tmp: str) -> ssl.SSLContext:
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    cert_path = os.path.join(tmp, f"chain{id(ctx)}.pem")
    key_path = os.path.join(tmp, f"key{id(ctx)}.pem")
    with open(cert_path, "wb") as f:
        f.write(b"".join(c.pem for c in chain))
    with open(key_path, "wb") as f:
        f.write(key_owner.key_pem)
    if ciphers:
        ctx.set_ciphers(ciphers)
    if min_v:
        ctx.minimum_version = min_v
    if max_v:
        ctx.maximum_version = max_v
    ctx.load_cert_chain(cert_path, key_path)
    if dh_params_pem:
        dh_path = os.path.join(tmp, f"dh{id(ctx)}.pem")
        with open(dh_path, "wb") as f:
            f.write(dh_params_pem)
        ctx.load_dh_params(dh_path)
    return ctx


def client_ctx(*, min_v=None, max_v=None, ciphers=None) -> ssl.SSLContext:
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    if ciphers:
        ctx.set_ciphers(ciphers)
    if min_v:
        ctx.minimum_version = min_v
    if max_v:
        ctx.maximum_version = max_v
    return ctx


def tls_flights(cctx: ssl.SSLContext, sctx: ssl.SSLContext, sni: Optional[str],
                exchange: List[Tuple[bytes, bytes]]) -> Tuple[List[Tuple[str, bytes]], bool]:
    """Run a real handshake + application exchange; return wire flights and success flag."""
    cin, cout, sin, sout = ssl.MemoryBIO(), ssl.MemoryBIO(), ssl.MemoryBIO(), ssl.MemoryBIO()
    c = cctx.wrap_bio(cin, cout, server_hostname=sni)
    s = sctx.wrap_bio(sin, sout, server_side=True)
    flights: List[Tuple[str, bytes]] = []

    def pump():
        moved = False
        d = cout.read()
        if d:
            flights.append(("c2s", d)); sin.write(d); moved = True
        d = sout.read()
        if d:
            flights.append(("s2c", d)); cin.write(d); moved = True
        return moved

    c_done = s_done = False
    failed = False
    for _ in range(50):
        for obj, is_client in ((c, True), (s, False)):
            if (is_client and c_done) or (not is_client and s_done):
                continue
            try:
                obj.do_handshake()
                if is_client:
                    c_done = True
                else:
                    s_done = True
            except (ssl.SSLWantReadError, ssl.SSLWantWriteError):
                pass
            except ssl.SSLError:
                failed = True
            pump()
        if failed or (c_done and s_done):
            pump()
            break
    if failed:
        pump()
        return flights, False

    for req, resp in exchange:
        c.write(req); pump()
        try:
            s.read(65536)
        except ssl.SSLWantReadError:
            pass
        pump()
        if resp:
            s.write(resp); pump()
            try:
                c.read(65536)
            except ssl.SSLWantReadError:
                pass
            pump()
    try:
        c.unwrap()
    except (ssl.SSLWantReadError, ssl.SSLError):
        pass
    pump()
    return flights, True


# --------------------------------------------------------------------- TCP
@dataclass
class Pkt:
    ts: float
    c2s: bool
    seq: int
    ack: int
    flags: int
    payload: bytes = b""


@dataclass
class Conversation:
    client_ip: str = "10.10.0.5"
    server_ip: str = "10.20.0.25"
    client_port: int = 49152
    server_port: int = 25
    ts: float = CAPTURE_EPOCH
    c_isn: int = 1000
    s_isn: int = 5000
    mss: int = 1400
    packets: List[Pkt] = field(default_factory=list)

    def __post_init__(self):
        self.c_seq = self.c_isn
        self.s_seq = self.s_isn

    def _tick(self, dt=0.002):
        self.ts += dt
        return self.ts

    def handshake(self):
        self.packets.append(Pkt(self._tick(), True, self.c_seq, 0, dpkt.tcp.TH_SYN))
        self.packets.append(Pkt(self._tick(), False, self.s_seq, self.c_seq + 1, dpkt.tcp.TH_SYN | dpkt.tcp.TH_ACK))
        self.c_seq += 1
        self.s_seq += 1
        self.packets.append(Pkt(self._tick(), True, self.c_seq, self.s_seq, dpkt.tcp.TH_ACK))
        return self

    def send(self, c2s: bool, data: bytes, mss: Optional[int] = None):
        mss = mss or self.mss
        for i in range(0, len(data), mss):
            seg = data[i:i + mss]
            if c2s:
                self.packets.append(Pkt(self._tick(), True, self.c_seq, self.s_seq,
                                        dpkt.tcp.TH_ACK | dpkt.tcp.TH_PUSH, seg))
                self.c_seq = (self.c_seq + len(seg)) % (1 << 32)
            else:
                self.packets.append(Pkt(self._tick(), False, self.s_seq, self.c_seq,
                                        dpkt.tcp.TH_ACK | dpkt.tcp.TH_PUSH, seg))
                self.s_seq = (self.s_seq + len(seg)) % (1 << 32)
        return self

    def client(self, data: bytes, mss=None):
        return self.send(True, data, mss)

    def server(self, data: bytes, mss=None):
        return self.send(False, data, mss)

    def flights(self, flights: List[Tuple[str, bytes]], mss=None):
        for d, data in flights:
            self.send(d == "c2s", data, mss)
        return self

    def close(self):
        self.packets.append(Pkt(self._tick(), True, self.c_seq, self.s_seq, dpkt.tcp.TH_FIN | dpkt.tcp.TH_ACK))
        self.c_seq += 1
        self.packets.append(Pkt(self._tick(), False, self.s_seq, self.c_seq, dpkt.tcp.TH_FIN | dpkt.tcp.TH_ACK))
        self.s_seq += 1
        self.packets.append(Pkt(self._tick(), True, self.c_seq, self.s_seq, dpkt.tcp.TH_ACK))
        return self


def _ip_bytes(addr: str) -> bytes:
    import ipaddress
    return ipaddress.ip_address(addr).packed


def build_frame(conv: Conversation, p: Pkt, link: str = "eth") -> bytes:
    src, dst = (conv.client_ip, conv.server_ip) if p.c2s else (conv.server_ip, conv.client_ip)
    sport, dport = (conv.client_port, conv.server_port) if p.c2s else (conv.server_port, conv.client_port)
    tcp = dpkt.tcp.TCP(sport=sport, dport=dport, seq=p.seq, ack=p.ack, flags=p.flags, win=65535, data=p.payload)
    if ":" in src:
        ip = dpkt.ip6.IP6(src=_ip_bytes(src), dst=_ip_bytes(dst), nxt=dpkt.ip.IP_PROTO_TCP, hlim=64, data=tcp)
        ip.plen = len(tcp)
        ethtype = dpkt.ethernet.ETH_TYPE_IP6
    else:
        ip = dpkt.ip.IP(src=_ip_bytes(src), dst=_ip_bytes(dst), p=dpkt.ip.IP_PROTO_TCP, ttl=64, data=tcp)
        ip.len = len(ip)
        ethtype = dpkt.ethernet.ETH_TYPE_IP
    if link == "eth":
        return bytes(dpkt.ethernet.Ethernet(src=b"\x02\x00\x00\x00\x00\x01", dst=b"\x02\x00\x00\x00\x00\x02",
                                            type=ethtype, data=ip))
    if link == "sll":
        # Linux cooked capture v1: 16-byte header.
        hdr = struct.pack("!HHH8sH", 0 if not p.c2s else 4, 1, 6, b"\x02\x00\x00\x00\x00\x01\x00\x00", ethtype)
        return hdr + bytes(ip)
    if link == "raw":
        return bytes(ip)
    raise ValueError(link)


LINKTYPES = {"eth": 1, "sll": 113, "raw": 101}


def write_capture(path: Path, convs: List[Tuple[Conversation, List[Pkt]]], link: str = "eth",
                  fmt: str = "pcap", extra_frames: Optional[List[Tuple[float, bytes]]] = None):
    frames = []
    for conv, pkts in convs:
        for p in pkts:
            frames.append((p.ts, build_frame(conv, p, link)))
    frames += extra_frames or []
    frames.sort(key=lambda x: x[0]) if fmt == "pcap-sorted" else None
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "wb") as f:
        if fmt == "pcapng":
            w = dpkt.pcapng.Writer(f, linktype=LINKTYPES[link])
        else:
            w = dpkt.pcap.Writer(f, linktype=LINKTYPES[link])
        for ts, fr in frames:
            w.writepkt(fr, ts=ts)


def write_truth(name: str, truth: dict):
    GT_DIR.mkdir(parents=True, exist_ok=True)
    truth = {"name": name, **truth}
    with open(GT_DIR / f"{name}.json", "w", encoding="utf-8") as f:
        json.dump(truth, f, indent=2)


def session(protocol, starttls_state, tls_version, findings, certificates=0, quality="complete",
            implicit_tls=False, handshake_status=None):
    return {"protocol": protocol, "starttls_state": starttls_state, "tls_version": tls_version,
            "findings": sorted(findings), "certificates": certificates, "reconstruction_quality": quality,
            "implicit_tls": implicit_tls, "handshake_status": handshake_status}


def truth(sessions, *, streams=None, notes="", synthetic_tls=False, extra=None):
    all_f = sorted({f for s in sessions for f in s["findings"]})
    t = {
        "expected_protocol": sessions[0]["protocol"] if sessions else None,
        "expected_tls": any(s["tls_version"] for s in sessions),
        "expected_reconstruction_quality": sessions[0]["reconstruction_quality"] if sessions else None,
        "expected_findings": all_f,
        "expected_anomalies": [],
        "expected_email_sessions": len(sessions),
        "expected_streams": streams if streams is not None else len(sessions),
        "expected_sessions": sessions,
        "tls_source": "hand-built (synthetic)" if synthetic_tls else "OpenSSL %s via memory BIO" % ssl.OPENSSL_VERSION,
        "certificate_validity_reference": "capture_time",
        "notes": notes,
    }
    t.update(extra or {})
    return t


# ------------------------------------------------------------- dialogues
SMTP_EHLO_RESP = b"250-mail.example.org Hello\r\n250-SIZE 35882577\r\n250-STARTTLS\r\n250 8BITMIME\r\n"
SMTP_EHLO_RESP_TLS = b"250-mail.example.org Hello\r\n250-SIZE 35882577\r\n250-AUTH PLAIN LOGIN\r\n250 8BITMIME\r\n"
SMTP_INNER = [(b"EHLO client.example.net\r\n", SMTP_EHLO_RESP_TLS),
              (b"MAIL FROM:<alice@example.net>\r\n", b"250 2.1.0 Ok\r\n"),
              (b"QUIT\r\n", b"221 2.0.0 Bye\r\n")]
IMAP_INNER = [(b"a3 LOGIN alice secret\r\n", b"a3 OK LOGIN completed\r\n"), (b"a4 LOGOUT\r\n", b"* BYE\r\na4 OK\r\n")]
POP3_INNER = [(b"USER alice\r\n", b"+OK\r\n"), (b"QUIT\r\n", b"+OK bye\r\n")]


def smtp_starttls(conv: Conversation, flights, banner=b"220 mail.example.org ESMTP Postfix\r\n", mss=None):
    conv.handshake().server(banner).client(b"EHLO client.example.net\r\n").server(SMTP_EHLO_RESP)
    conv.client(b"STARTTLS\r\n").server(b"220 2.0.0 Ready to start TLS\r\n")
    conv.flights(flights, mss)
    return conv.close()


def imap_starttls(conv: Conversation, flights, mss=None):
    conv.handshake().server(b"* OK [CAPABILITY IMAP4rev1 STARTTLS LOGINDISABLED] Dovecot ready.\r\n")
    conv.client(b"a1 CAPABILITY\r\n").server(b"* CAPABILITY IMAP4rev1 STARTTLS LOGINDISABLED\r\na1 OK\r\n")
    conv.client(b"a2 STARTTLS\r\n").server(b"a2 OK Begin TLS negotiation now\r\n")
    conv.flights(flights, mss)
    return conv.close()


def pop3_stls(conv: Conversation, flights, mss=None):
    conv.handshake().server(b"+OK Dovecot POP3 ready.\r\n")
    conv.client(b"CAPA\r\n").server(b"+OK\r\nSTLS\r\nUSER\r\n.\r\n")
    conv.client(b"STLS\r\n").server(b"+OK Begin TLS negotiation\r\n")
    conv.flights(flights, mss)
    return conv.close()


# ------------------------------------------------------------ scenarios
TLS1, TLS12, TLS13 = ssl.TLSVersion.TLSv1, ssl.TLSVersion.TLSv1_2, ssl.TLSVersion.TLSv1_3


def run_tls(tmp, chain, key_owner, *, sni="mail.example.org", exchange=SMTP_INNER, s_kw=None, c_kw=None):
    sctx = server_ctx(chain, key_owner, tmp=tmp, **(s_kw or {}))
    cctx = client_ctx(**(c_kw or {}))
    flights, ok = tls_flights(cctx, sctx, sni, exchange)
    return flights, ok


def crafted_hello_records(client_suites: List[int], server_suite: int, version=0x0303, sni="mail.example.org",
                          cert_der: Optional[bytes] = None) -> Tuple[bytes, bytes]:
    """Hand-built ClientHello / ServerHello(+Certificate+ServerHelloDone). Used only where OpenSSL
    cannot negotiate the suite under test."""
    def rec(ct, body):
        return bytes([ct, 3, 3 if version >= 0x0303 else version & 0xFF]) + struct.pack("!H", len(body)) + body

    def hs(t, body):
        return bytes([t]) + len(body).to_bytes(3, "big") + body
    host = sni.encode()
    sni_ext = struct.pack("!HH", 0, len(host) + 5) + struct.pack("!HBH", len(host) + 3, 0, len(host)) + host
    suites = b"".join(struct.pack("!H", s) for s in client_suites)
    ch = struct.pack("!H", version) + os.urandom(32) + b"\x00" + struct.pack("!H", len(suites)) + suites + b"\x01\x00"
    ch += struct.pack("!H", len(sni_ext)) + sni_ext
    sh = struct.pack("!H", version) + os.urandom(32) + b"\x00" + struct.pack("!H", server_suite) + b"\x00"
    server = hs(2, sh)
    if cert_der:
        entry = len(cert_der).to_bytes(3, "big") + cert_der
        server += hs(11, len(entry).to_bytes(3, "big") + entry)
    server += hs(14, b"")
    return rec(22, hs(1, ch)), rec(22, server)


def build_all():
    PCAP_DIR.mkdir(parents=True, exist_ok=True)
    tmp = tempfile.mkdtemp(prefix="sms_fixtures_")
    port = iter(range(50001, 50999))

    # 1. Plaintext SMTP baseline (no STARTTLS offered)
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP Postfix\r\n").client(b"EHLO client.example.net\r\n")
    c.server(b"250-mail.example.org\r\n250 8BITMIME\r\n").client(b"MAIL FROM:<alice@example.net>\r\n")
    c.server(b"250 Ok\r\n").client(b"QUIT\r\n").server(b"221 Bye\r\n").close()
    write_capture(PCAP_DIR / "clean_baseline.pcap", [(c, c.packets)])
    write_truth("clean_baseline", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001"])],
                                        notes="Plaintext SMTP; server does not advertise STARTTLS."))

    # 2. TCP out-of-order: server banner split in two segments delivered reversed.
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP ready\r\n", mss=12)
    banner_segs = c.packets[3:]
    c.packets[3:] = list(reversed(banner_segs))
    c.client(b"EHLO client.example.net\r\n").server(b"250 mail.example.org\r\n").close()
    write_capture(PCAP_DIR / "out_of_order.pcap", [(c, c.packets)])
    write_truth("out_of_order", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001"])],
                                      notes="Banner segments arrive in reverse order; reassembly must restore them."))

    # 3. Retransmissions: identical duplicate of a server segment.
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP ready\r\n")
    c.packets.append(Pkt(c._tick(0.2), False, c.packets[-1].seq, c.packets[-1].ack, c.packets[-1].flags,
                         c.packets[-1].payload))
    c.client(b"EHLO client.example.net\r\n").server(b"250 mail.example.org\r\n").close()
    write_capture(PCAP_DIR / "retransmissions.pcap", [(c, c.packets)])
    write_truth("retransmissions", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001"])],
                                         notes="One identical retransmission; data must be delivered once."))

    # 4. Missing segment: middle of the server's EHLO response is lost.
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP ready\r\n").client(b"EHLO client.example.net\r\n")
    c.server(b"250-mail.example.org\r\n250-SIZE 1000\r\n250 8BITMIME\r\n", mss=20)
    del c.packets[-2]
    c.close()
    write_capture(PCAP_DIR / "missing_segment.pcap", [(c, c.packets)])
    write_truth("missing_segment", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001"], quality="partial")],
                                         notes="A lost server segment leaves a permanent gap."))

    # 5. Conflicting overlap (evasion indicator)
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP ready\r\n").client(b"EHLO client.example.net\r\n")
    last = c.packets[-1]
    c.packets.append(Pkt(c._tick(), True, last.seq, last.ack, last.flags, b"EHLO attacker.invalid\r\n"))
    c.server(b"250 mail.example.org\r\n").close()
    write_capture(PCAP_DIR / "tcp_overlap_conflict.pcap", [(c, c.packets)])
    write_truth("tcp_overlap_conflict", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001"],
                                                       quality="inconsistent")],
                                              notes="Retransmission with different bytes: first copy wins, "
                                                    "stream flagged inconsistent."))

    # 6. SMTP STARTTLS -> TLS 1.2 ECDHE with full chain (secure baseline)
    root, inter, leaf = pki_chain()
    flights, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"min_v": TLS12, "max_v": TLS12})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port), server_port=587), flights)
    write_capture(PCAP_DIR / "smtp_starttls_tls12_chain.pcap", [(c, c.packets)])
    write_truth("smtp_starttls_tls12_chain", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", [], certificates=2,
                                                            handshake_status="complete")],
                                                   notes="Leaf + intermediate, linked by signature; SNI matches.",
                                                   extra={"expected_chain_status": "linked"}))

    # 7. SMTP STARTTLS -> TLS 1.3 (certificates encrypted)
    root, inter, leaf = pki_chain()
    flights, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"min_v": TLS13})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), flights)
    write_capture(PCAP_DIR / "smtp_starttls_tls13_secure.pcap", [(c, c.packets)])
    write_truth("smtp_starttls_tls13_secure", truth(
        [session("SMTP", "TLS_ESTABLISHED", "TLSv1.3", [], certificates=0, handshake_status="complete")],
        notes="TLS 1.3 encrypts the Certificate message: certificates are NOT observable passively.",
        extra={"expected_certificate_visibility": "encrypted_tls13"}))

    # 8. Weak / deprecated: TLS 1.0, static RSA, self-signed RSA-1024 expired at capture time
    weak = issue("mail.example.org", san=["mail.example.org"], key_bits=1024,
                 not_before=CAPTURE_DT - timedelta(days=400), not_after=CAPTURE_DT - timedelta(days=35))
    flights, ok = run_tls(tmp, [weak], weak,
                          s_kw={"min_v": TLS1, "max_v": TLS1, "ciphers": "AES128-SHA:@SECLEVEL=0"},
                          c_kw={"min_v": TLS1, "max_v": TLS1, "ciphers": "AES128-SHA:@SECLEVEL=0"})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), flights)
    write_capture(PCAP_DIR / "smtp_weak_deprecated.pcap", [(c, c.packets)])
    write_truth("smtp_weak_deprecated", truth([session(
        "SMTP", "TLS_ESTABLISHED", "TLSv1.0", ["TLS-001", "TLS-004", "CERT-001", "CERT-003", "CERT-005"],
        certificates=1, handshake_status="complete")],
        notes="TLS 1.0 + TLS_RSA_WITH_AES_128_CBC_SHA (no forward secrecy); self-signed 1024-bit RSA "
              "certificate that expired 35 days before the capture."))

    # 9. IMAP STARTTLS TLS 1.2, self-signed leaf
    ss = issue("imap.example.org", san=["imap.example.org"])
    flights, ok = run_tls(tmp, [ss], ss, sni="imap.example.org", exchange=IMAP_INNER,
                          s_kw={"max_v": TLS12, "ciphers": "ECDHE-RSA-AES128-GCM-SHA256"})
    assert ok
    c = imap_starttls(Conversation(client_port=next(port), server_port=143), flights)
    write_capture(PCAP_DIR / "imap_starttls_tls12.pcap", [(c, c.packets)])
    write_truth("imap_starttls_tls12", truth([session("IMAP", "TLS_ESTABLISHED", "TLSv1.2", ["CERT-005"],
                                                      certificates=1, handshake_status="complete")],
                                             notes="IMAP LOGIN happens inside TLS, so it is not plaintext auth."))

    # 10. IMAP segmented: TLS records split across 90-byte TCP segments
    root, inter, leaf = pki_chain("imap.example.org")
    flights, ok = run_tls(tmp, [leaf, inter], leaf, sni="imap.example.org", exchange=IMAP_INNER,
                          s_kw={"max_v": TLS12})
    assert ok
    c = imap_starttls(Conversation(client_port=next(port), server_port=143), flights, mss=90)
    write_capture(PCAP_DIR / "layer_b_imap_tls12_segmented.pcap", [(c, c.packets)])
    write_truth("layer_b_imap_tls12_segmented", truth([session("IMAP", "TLS_ESTABLISHED", "TLSv1.2", [],
                                                               certificates=2, handshake_status="complete")],
                                                      notes="Every TLS record spans many 90-byte TCP segments."))

    # 11. SMTP TLS 1.2 static-RSA suite, expired weak self-signed cert
    weak = issue("mail.example.org", san=["mail.example.org"], key_bits=1024,
                 not_before=CAPTURE_DT - timedelta(days=500), not_after=CAPTURE_DT - timedelta(days=1))
    flights, ok = run_tls(tmp, [weak], weak, s_kw={"max_v": TLS12, "ciphers": "AES256-SHA:@SECLEVEL=0"},
                          c_kw={"ciphers": "AES256-SHA:@SECLEVEL=0", "max_v": TLS12})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), flights)
    write_capture(PCAP_DIR / "layer_b_smtp_tls12_weak.pcap", [(c, c.packets)])
    write_truth("layer_b_smtp_tls12_weak", truth([session(
        "SMTP", "TLS_ESTABLISHED", "TLSv1.2", ["TLS-004", "CERT-001", "CERT-003", "CERT-005"],
        certificates=1, handshake_status="complete")],
        notes="TLS_RSA_WITH_AES_256_CBC_SHA; self-signed RSA-1024 expired one day before capture."))

    # 12. SMTP TLS 1.3 with small segments
    root, inter, leaf = pki_chain()
    flights, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"min_v": TLS13})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), flights, mss=100)
    write_capture(PCAP_DIR / "layer_b_smtp_tls13_secure.pcap", [(c, c.packets)])
    write_truth("layer_b_smtp_tls13_secure", truth(
        [session("SMTP", "TLS_ESTABLISHED", "TLSv1.3", [], certificates=0, handshake_status="complete")],
        notes="TLS 1.3 in 100-byte segments.", extra={"expected_certificate_visibility": "encrypted_tls13"}))

    # 13. SMTP STARTTLS rejected (454) and mail continues in plaintext
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP\r\n").client(b"EHLO client.example.net\r\n")
    c.server(SMTP_EHLO_RESP).client(b"STARTTLS\r\n").server(b"454 4.7.0 TLS not available due to temporary reason\r\n")
    c.client(b"MAIL FROM:<alice@example.net>\r\n").server(b"250 Ok\r\n").client(b"QUIT\r\n").server(b"221 Bye\r\n").close()
    write_capture(PCAP_DIR / "smtp_starttls_downgrade.pcap", [(c, c.packets)])
    write_truth("smtp_starttls_downgrade", truth([session("SMTP", "STARTTLS_REJECTED", None,
                                                          ["STLS-001", "PROTO-001"])],
                                                 notes="454 rejection then plaintext MAIL FROM. Consistent with "
                                                       "misconfiguration or STARTTLS stripping (not provable)."))

    # 14. POP3 STLS rejected
    c = Conversation(client_port=next(port), server_port=110)
    c.handshake().server(b"+OK POP3 ready\r\n").client(b"STLS\r\n").server(b"-ERR Command not understood\r\n")
    c.client(b"QUIT\r\n").server(b"+OK bye\r\n").close()
    write_capture(PCAP_DIR / "pop3_starttls_rejected.pcap", [(c, c.packets)])
    write_truth("pop3_starttls_rejected", truth([session("POP3", "STARTTLS_REJECTED", None, ["STLS-001", "PROTO-001"])]))

    # 15. Truncated capture: STARTTLS accepted, ClientHello seen, capture ends mid ServerHello flight
    root, inter, leaf = pki_chain()
    flights, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12})
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP\r\n").client(b"EHLO client.example.net\r\n").server(SMTP_EHLO_RESP)
    c.client(b"STARTTLS\r\n").server(b"220 2.0.0 Ready to start TLS\r\n")
    c.send(True, flights[0][1])
    c.send(False, flights[1][1][:60])  # capture stops 60 bytes into the server flight
    write_capture(PCAP_DIR / "smtp_starttls_truncated.pcap", [(c, c.packets)])
    write_truth("smtp_starttls_truncated", truth([session("SMTP", "TLS_HANDSHAKE_STARTED", None, [],
                                                          handshake_status="incomplete")],
                                                 notes="ClientHello observed, ServerHello incomplete: version, "
                                                       "cipher and certificates are UNKNOWN, not insecure."))

    # 16. Implicit TLS: IMAPS 993 (TLS 1.2), POP3S 995 (TLS 1.3), SMTPS 465 (TLS 1.2) in one capture
    convs = []
    root, inter, leaf = pki_chain("imap.example.org")
    fl, ok = run_tls(tmp, [leaf, inter], leaf, sni="imap.example.org", exchange=IMAP_INNER, s_kw={"max_v": TLS12})
    assert ok
    c1 = Conversation(client_port=next(port), server_port=993).handshake().flights(fl).close()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, sni="imap.example.org", exchange=POP3_INNER, s_kw={"min_v": TLS13})
    assert ok
    c2 = Conversation(client_port=next(port), server_port=995, ts=CAPTURE_EPOCH + 1).handshake().flights(fl).close()
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12})
    assert ok
    c3 = Conversation(client_port=next(port), server_port=465, ts=CAPTURE_EPOCH + 2).handshake().flights(fl).close()
    write_capture(PCAP_DIR / "implicit_tls_mixed.pcap", [(c1, c1.packets), (c2, c2.packets), (c3, c3.packets)])
    write_truth("implicit_tls_mixed", truth([
        session("IMAP", "TLS_ESTABLISHED", "TLSv1.2", [], certificates=2, implicit_tls=True, handshake_status="complete"),
        session("POP3", "TLS_ESTABLISHED", "TLSv1.3", [], certificates=0, implicit_tls=True, handshake_status="complete"),
        session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", [], certificates=2, implicit_tls=True, handshake_status="complete"),
    ], notes="Implicit TLS on 993/995/465 must never be reported as plaintext."))

    # 17. Non-standard port SMTP with STARTTLS (banner-based detection)
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port), server_port=10025), fl)
    write_capture(PCAP_DIR / "smtp_nonstandard_port.pcap", [(c, c.packets)])
    write_truth("smtp_nonstandard_port", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", [], certificates=2,
                                                        handshake_status="complete")],
                                               notes="Port 10025: detection must come from the banner."))

    # 18. Unrelated traffic only: HTTP, SSH on 2222, TLS on 443 -> no email sessions
    h = Conversation(client_port=next(port), server_port=80).handshake()
    h.client(b"GET / HTTP/1.1\r\nHost: example.org\r\n\r\n").server(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n").close()
    s = Conversation(client_port=next(port), server_port=2222, ts=CAPTURE_EPOCH + 1).handshake()
    s.server(b"SSH-2.0-OpenSSH_9.6\r\n").client(b"SSH-2.0-OpenSSH_9.6\r\n").close()
    root, inter, leaf = pki_chain("www.example.org")
    fl, ok = run_tls(tmp, [leaf, inter], leaf, sni="www.example.org", exchange=[(b"GET / HTTP/1.1\r\n\r\n", b"HTTP/1.1 200 OK\r\n\r\n")])
    t = Conversation(client_port=next(port), server_port=443, ts=CAPTURE_EPOCH + 2).handshake().flights(fl).close()
    write_capture(PCAP_DIR / "unrelated_traffic.pcap", [(h, h.packets), (s, s.packets), (t, t.packets)])
    write_truth("unrelated_traffic", truth([], streams=3, notes="No email: posture must be UNKNOWN, not Excellent.",
                                           extra={"expected_posture_status": "Unknown"}))

    # 19. Plaintext authentication (AUTH LOGIN before TLS)
    c = Conversation(client_port=next(port), server_port=587)
    c.handshake().server(b"220 mail.example.org ESMTP\r\n").client(b"EHLO client.example.net\r\n")
    c.server(b"250-mail.example.org\r\n250 AUTH PLAIN LOGIN\r\n").client(b"AUTH LOGIN\r\n").server(b"334 VXNlcm5hbWU6\r\n")
    c.client(b"YWxpY2U=\r\n").server(b"334 UGFzc3dvcmQ6\r\n").client(b"c2VjcmV0\r\n").server(b"235 Authentication successful\r\n")
    c.client(b"QUIT\r\n").server(b"221 Bye\r\n").close()
    write_capture(PCAP_DIR / "smtp_plaintext_auth.pcap", [(c, c.packets)])
    write_truth("smtp_plaintext_auth", truth([session("SMTP", "PLAINTEXT", None, ["PROTO-001", "PROTO-002"])],
                                             notes="AUTH LOGIN in cleartext. Credential values must not be stored.",
                                             extra={"forbidden_strings_in_outputs": ["YWxpY2U=", "c2VjcmV0"]}))

    # 20. STARTTLS with pipelined command (injection indicator) then TLS 1.2
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12})
    assert ok
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP\r\n").client(b"EHLO client.example.net\r\n").server(SMTP_EHLO_RESP)
    c.client(b"STARTTLS\r\nRSET\r\n").server(b"220 2.0.0 Ready to start TLS\r\n").flights(fl).close()
    write_capture(PCAP_DIR / "smtp_starttls_pipelined.pcap", [(c, c.packets)])
    write_truth("smtp_starttls_pipelined", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", ["STLS-003"],
                                                          certificates=2, handshake_status="complete")]))

    # 21. SNI / certificate hostname mismatch
    root, inter, leaf = pki_chain("other.example.com", san=["other.example.com"])
    fl, ok = run_tls(tmp, [leaf, inter], leaf, sni="mail.example.org", s_kw={"max_v": TLS12})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), fl)
    write_capture(PCAP_DIR / "smtp_tls12_sni_mismatch.pcap", [(c, c.packets)])
    write_truth("smtp_tls12_sni_mismatch", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", ["CERT-006"],
                                                          certificates=2, handshake_status="complete")]))

    # 22. Handshake failure: client requires TLS 1.3, server caps at TLS 1.2 -> protocol_version alert
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12}, c_kw={"min_v": TLS13})
    assert not ok
    c = smtp_starttls(Conversation(client_port=next(port)), fl)
    write_capture(PCAP_DIR / "smtp_tls_handshake_failure.pcap", [(c, c.packets)])
    write_truth("smtp_tls_handshake_failure", truth([session("SMTP", "TLS_FAILED", None, ["TLS-002"],
                                                             handshake_status="failed")],
                                                    notes="Fatal protocol_version alert; no ServerHello."))

    # 23. Weak DH parameters (1024-bit DHE)
    params = dh.generate_parameters(generator=2, key_size=1024)
    dh_pem = params.parameter_bytes(serialization.Encoding.PEM, serialization.ParameterFormat.PKCS3)
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf,
                     s_kw={"max_v": TLS12, "ciphers": "DHE-RSA-AES128-GCM-SHA256:@SECLEVEL=0", "dh_params_pem": dh_pem},
                     c_kw={"ciphers": "DHE-RSA-AES128-GCM-SHA256:@SECLEVEL=0", "max_v": TLS12})
    assert ok
    c = smtp_starttls(Conversation(client_port=next(port)), fl)
    write_capture(PCAP_DIR / "smtp_tls12_weak_dh.pcap", [(c, c.packets)])
    write_truth("smtp_tls12_weak_dh", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", ["TLS-005"],
                                                     certificates=2, handshake_status="complete")],
                                            notes="DHE with a 1024-bit group (Logjam-class weakness)."))

    # 24. Synthetic 3DES negotiation (OpenSSL 3 cannot negotiate it)
    ss = issue("mail.example.org", san=["mail.example.org"])
    ch, sh = crafted_hello_records([0x000A, 0x0005, 0xC02F], 0x000A, cert_der=ss.der)
    c = Conversation(client_port=next(port))
    c.handshake().server(b"220 mail.example.org ESMTP\r\n").client(b"EHLO x\r\n").server(SMTP_EHLO_RESP)
    c.client(b"STARTTLS\r\n").server(b"220 Go ahead\r\n").client(ch).server(sh).close()
    write_capture(PCAP_DIR / "smtp_tls12_3des_synthetic.pcap", [(c, c.packets)])
    write_truth("smtp_tls12_3des_synthetic", truth(
        [session("SMTP", "TLS_HANDSHAKE_STARTED", "TLSv1.2", ["TLS-003", "TLS-004", "TLS-006", "CERT-005"],
                 certificates=1, handshake_status="incomplete")],
        synthetic_tls=True,
        notes="Hand-built hellos: server selects TLS_RSA_WITH_3DES_EDE_CBC_SHA; client also offers RC4."))

    # 25. IPv6 SMTP STARTTLS TLS 1.3
    root, inter, leaf = pki_chain()
    fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"min_v": TLS13})
    assert ok
    c = smtp_starttls(Conversation(client_ip="2001:db8::5", server_ip="2001:db8::25", client_port=next(port)), fl)
    write_capture(PCAP_DIR / "ipv6_smtp_tls13.pcap", [(c, c.packets)])
    write_truth("ipv6_smtp_tls13", truth([session("SMTP", "TLS_ESTABLISHED", "TLSv1.3", [], handshake_status="complete")]))

    # 26. Linux cooked capture (SLL) POP3 STLS TLS 1.2
    ss = issue("pop.example.org", san=["pop.example.org"])
    fl, ok = run_tls(tmp, [ss], ss, sni="pop.example.org", exchange=POP3_INNER, s_kw={"max_v": TLS12})
    assert ok
    c = pop3_stls(Conversation(client_port=next(port), server_port=110), fl)
    write_capture(PCAP_DIR / "sll_pop3_stls_tls12.pcap", [(c, c.packets)], link="sll")
    write_truth("sll_pop3_stls_tls12", truth([session("POP3", "TLS_ESTABLISHED", "TLSv1.2", ["CERT-005"],
                                                      certificates=1, handshake_status="complete")],
                                             notes="Linux SLL link layer (DLT 113)."))

    # 27. PCAPNG container
    c = Conversation(client_port=next(port), server_port=143)
    c.handshake().server(b"* OK IMAP4rev1 ready\r\n").client(b"a1 LOGIN alice secret\r\n").server(b"a1 OK\r\n").close()
    write_capture(PCAP_DIR / "pcapng_imap_plaintext.pcapng", [(c, c.packets)], fmt="pcapng")
    write_truth("pcapng_imap_plaintext", truth([session("IMAP", "PLAINTEXT", None, ["PROTO-001", "PROTO-002"])],
                                               extra={"forbidden_strings_in_outputs": ["secret"]}))

    # 28. Mixed estate for ML: 11 similar TLS 1.2 ECDHE sessions + 1 TLS 1.0 static-RSA outlier
    convs = []
    root, inter, leaf = pki_chain()
    for i in range(11):
        fl, ok = run_tls(tmp, [leaf, inter], leaf, s_kw={"max_v": TLS12, "ciphers": "ECDHE-RSA-AES128-GCM-SHA256"})
        assert ok
        convs.append(smtp_starttls(Conversation(client_ip=f"10.10.1.{i + 10}", client_port=next(port),
                                                ts=CAPTURE_EPOCH + i * 7), fl))
    weak = issue("legacy.example.org", san=["legacy.example.org"], key_bits=1024)
    fl, ok = run_tls(tmp, [weak], weak, sni="legacy.example.org",
                     s_kw={"min_v": TLS1, "max_v": TLS1, "ciphers": "AES128-SHA:@SECLEVEL=0"},
                     c_kw={"min_v": TLS1, "max_v": TLS1, "ciphers": "AES128-SHA:@SECLEVEL=0"})
    assert ok
    convs.append(smtp_starttls(Conversation(client_ip="10.10.9.9", server_ip="10.20.0.99", client_port=next(port),
                                            ts=CAPTURE_EPOCH + 100), fl))
    write_capture(PCAP_DIR / "ml_mixed_estate.pcap", [(c, c.packets) for c in convs])
    sessions = [session("SMTP", "TLS_ESTABLISHED", "TLSv1.2", [], certificates=2, handshake_status="complete")
                for _ in range(11)]
    sessions.append(session("SMTP", "TLS_ESTABLISHED", "TLSv1.0", ["TLS-001", "TLS-004", "CERT-003", "CERT-005"],
                            certificates=1, handshake_status="complete"))
    write_truth("ml_mixed_estate", truth(sessions, notes="12 TLS sessions; the TLS 1.0 session is the expected "
                                                         "statistical outlier (unsupervised; not a label).",
                                         extra={"expected_ml_outlier_client": "10.10.9.9"}))

    print(f"Fixtures written to {PCAP_DIR}")


if __name__ == "__main__":
    build_all()
